<template><aside v-if="open" class="debug"><header><b>Performance Debug</b><button @click="open=false">×</button></header><section v-if="s"><h4>FRAME</h4><p>FPS {{s.fps}} · Frame {{s.frameMs.average}} ms · P95 {{s.frameMs.p95}} ms</p><p>CPU {{s.cpuMs.update}} / Render {{s.cpuMs.render}} ms</p><h4>RENDERER</h4><p>Calls {{s.render.calls}} · Triangles {{s.render.triangles.toLocaleString()}}</p><p>Geometries {{s.memory.geometries}} · Textures {{s.memory.textures}}</p><h4>ADAPTIVE QUALITY</h4><p>Quality {{quality}}</p></section></aside><button v-else class="debug-toggle" @click="open=true">Performance</button></template>
<script setup lang="ts">import { ref, computed } from 'vue'; import { usePerformanceStore } from '../stores/PerformanceStore'; const open=ref(true); const store=usePerformanceStore(); const s=computed(()=>store.snapshot); const quality=computed(() => { const value = s.value?.metrics?.quality; return typeof value === 'string' ? value.toUpperCase() : 'N/A'; });</script>
<style scoped>.debug{position:fixed;left:16px;bottom:16px;width:340px;max-height:min(78vh,620px);overflow-y:auto;overflow-x:hidden;padding:12px;background:rgba(3,12,22,.68);color:rgba(184,245,255,.82);font:11px Consolas,monospace;z-index:1000;border:1px solid rgba(53,215,197,.62)}.debug header{display:flex;justify-content:space-between}.debug h4{color:rgba(81,242,166,.82);margin:12px 0 5px;border-bottom:1px solid rgba(22,75,82,.62);padding-bottom:3px}.debug p{margin:4px 0;line-height:1.35}.debug-toggle{position:fixed;left:16px;bottom:16px}</style>

